<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Plus, Trash2, Code2 } from 'lucide-vue-next'
import type { Editor } from '../lib/editor'
import { newId } from '../lib/model'
import { pythonRuntimeId } from '../lib/platform'
const props=defineProps<{editor:Editor}>()
const selectedId=ref(''), error=ref('')
const modules=computed(()=>props.editor.project.value.codeModules??[])
const selected=computed(()=>modules.value.find(item=>item.id===selectedId.value)??modules.value[0])
watch(()=>selected.value?.id,()=>error.value='')
function add(){let index=1;while(modules.value.some(item=>item.name===`module_${index}`))index++;const id=newId('module');props.editor.mutate(project=>{project.schemaVersion=4;project.codeModules??=[];project.codeModules.push({id,name:`module_${index}`,source:'def process(value):\n    return value\n'});project.python??={runtimeId:pythonRuntimeId.value,dependencyLock:[]}});selectedId.value=id}
function rename(event:Event){if(!selected.value)return;const name=(event.target as HTMLInputElement).value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)||modules.value.some(item=>item.id!==selected.value!.id&&item.name===name)){error.value='导入名称须为唯一 Python 标识符（字母、数字、下划线，不能以数字开头）。';return}props.editor.mutate(()=>selected.value!.name=name);error.value=''}
function source(value:string){if(selected.value)props.editor.mutate(()=>selected.value!.source=value)}
function remove(){if(selected.value)props.editor.mutate(project=>project.codeModules=modules.value.filter(item=>item.id!==selected.value!.id))}
function indent(event:KeyboardEvent){const input=event.target as HTMLTextAreaElement;input.setRangeText('    ',input.selectionStart,input.selectionEnd,'end');source(input.value)}
</script>
<template><section class="code-modules" aria-label="Python 代码库"><aside><div class="module-list-heading"><strong>共享 Python 代码库</strong><button class="icon-button" title="添加代码库" :disabled="editor.readOnly.value" @click="add"><Plus :size="16"/></button></div><button v-for="item in modules" :key="item.id" class="module-item" :class="{active:selected?.id===item.id}" @click="selectedId=item.id"><Code2 :size="15"/><span>{{item.name}}.py</span></button><p>在代码节点中使用 import 导入。每次运行使用启动时的工程版本。</p></aside><div v-if="selected" class="module-content"><div class="module-heading"><label>导入名称<input :key="`${selected.id}:${selected.name}`" :value="selected.name" :disabled="editor.readOnly.value" aria-label="Python 导入名称" spellcheck="false" @change="rename"></label><code>import {{selected.name}}</code><button class="icon-button" title="删除代码库" :disabled="editor.readOnly.value" @click="remove"><Trash2 :size="16"/></button></div><p v-if="error" class="error-copy" role="alert">{{error}}</p><p class="module-note">修改导入名称后，请同步更新引用该库的 import 语句。删除可撤销。</p><textarea :key="selected.id" class="code-input module-source" :value="selected.source" :disabled="editor.readOnly.value" aria-label="共享 Python 源码" spellcheck="false" @input="source(($event.target as HTMLTextAreaElement).value)" @keydown.tab.prevent="indent"/></div><div v-else class="module-empty"><Code2 :size="36"/><p>将多个代码节点共用的函数放入代码库。</p><button :disabled="editor.readOnly.value" @click="add">添加代码库</button></div></section></template>
<style scoped>.code-modules{display:flex;flex:1;min-height:0;min-width:0;background:#fff}.code-modules aside{width:200px;flex-shrink:0;border-right:1px solid var(--line);padding:10px;overflow:auto}.module-list-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px}.module-item{width:100%;display:flex;align-items:center;gap:8px;padding:8px;text-align:left;border:0;background:transparent;cursor:pointer;font-size:12px}.module-item span{overflow:hidden;text-overflow:ellipsis}.module-item.active{background:#e8f2fc;color:#0f6cbd}.code-modules aside p,.module-note{font-size:11px;color:#68788a;line-height:1.6}.module-content{display:flex;flex:1;min-width:0;min-height:0;flex-direction:column;padding:12px;gap:8px}.module-heading{display:flex;align-items:center;gap:12px;min-width:0}.module-heading label{display:flex;flex-direction:row;align-items:center;gap:8px;margin:0;font-size:12px}.module-heading input{width:170px;font-size:12px}.module-heading code{flex:1;overflow:hidden;text-overflow:ellipsis;font-size:12px}.module-source{flex:1;width:100%;min-height:180px;resize:none;white-space:pre;tab-size:4;font-size:13px;line-height:1.6}.module-note{margin:0}.module-empty{flex:1;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:#68788a;font-size:13px}@media(max-width:900px){.code-modules aside{width:150px}.module-heading code{display:none}}</style>
